/**
 * Traditional Chinese, and the pack the Cantonese one is built on.
 *
 * Hoisted out of TRANSLATIONS so `yue` can spread it: a property of an object
 * literal can't be referenced from a sibling property, and `yue` used to spread
 * TRANSLATIONS_BASE.zh instead. That worked, but every key yue didn't override
 * then reached a Hong Kong reader in Simplified characters, which was 278 of
 * them. Traditional wording from Taiwan is a fair fallback for a Cantonese
 * reader; Simplified glyphs are not.
 *
 * So anything missing here now leaks into two languages rather than one.
 */
