    'cal.desc.off': '不校準 —— 直接顯示原始藥物動力學模型。',
    'cal.recommended': '推薦',
    'cal.off.pro.1': '模型完全透明，不受單次異常檢驗影響',
    'cal.off.con.1': '不會根據你的實測值做個人化修正',
    'cal.ekf': 'EKF',
    'cal.ou_kalman': 'OU-Kalman',
    'cal.mipd': 'Hybrid-MIPD',
    'cal.desc.ekf':
        '擴展卡爾曼濾波。依時間順序逐一處理你的檢驗，持續估計個人幅度與清除率及其不確定度。永久記憶——每次檢驗都會留下痕跡。',
    'cal.desc.ou_kalman':
        'Ornstein–Uhlenbeck 卡爾曼平滑。把校正量視為會漂移、並向模型回歸的水準：每次檢驗的影響約兩週後衰減回模型。追蹤隨時間變化的水準，而非單一固定倍率。',
    'cal.desc.mipd':
        '模型指導的精準給藥。在族群先驗下對幅度與清除率做 MAP 擬合，採用穩健（Student-t）似然：資料稀疏時向族群收縮，並能抵禦單一異常值。',
    'cal.ekf.pro.1': '同時學習幅度與清除率，每次檢驗都更新',
    'cal.ekf.pro.2': '追蹤自身不確定度；有界，不會跑飛',
    'cal.ekf.con.1': '永久記憶——舊的檢驗會持續牽引估計',
    'cal.ou_kalman.pro.1': '追蹤隨時間漂移的水準，而非固定倍率',
    'cal.ou_kalman.pro.2': '近期檢驗權重較大；陳舊資料自動淡出',
    'cal.ou_kalman.con.1': '只校正水準——不改變曲線形狀或半衰期',
    'cal.mipd.pro.1': '對異常值穩健；資料少時依靠族群先驗',
    'cal.mipd.pro.2': '學習幅度與清除率；1 次檢驗即可生效',
    'cal.mipd.con.1': '需 3 次以上、時間分散的檢驗才能調整半衰期',
    'cal.history': '套用於歷史',
    'cal.forward': '前向',
    'cal.retrospective': '回顧',
    'cal.desc.forward': '因果方式——每個時點只使用當時已有的檢驗，新增檢驗不會改寫過去的估計。',
    'cal.desc.retrospective': '平滑方式——用全部檢驗重新估計整段歷史。事後更準確；新檢驗可能修正較早的估計。',
