            '拡張カルマンフィルタ。検査を時系列順に処理し、個人の振幅とクリアランスの推定値を不確かさとともに保持します。記憶は永続——どの検査も痕跡を残します。',
        'cal.desc.ou_kalman':
            'オルンシュタイン–ウーレンベック型カルマン平滑化。補正量をドリフトしつつモデルへ回帰する水準として扱い、各検査の影響は約2週間でモデルへ減衰します。固定係数ではなく時間変化する水準を追跡します。',
        'cal.desc.mipd':
            'モデル情報に基づく精密投与。母集団事前分布の下で振幅とクリアランスをMAP推定し、頑健な（Student-t）尤度を用います。検査が少なければ母集団へ縮約し、単一の外れ値にも動じません。',
        'cal.ekf.pro.1': '振幅とクリアランスを同時に学習し、検査ごとに更新',
