        'cal.ou_kalman.pro.2': '新しい検査ほど重く、古いものは自然に薄れる',
        'cal.ou_kalman.con.1': '水準のみ補正——曲線の形や半減期は変えない',
        'cal.mipd.pro.1': '外れ値に頑健；データが少なければ母集団に頼る',
        'cal.mipd.pro.2': '振幅とクリアランスを学習；検査1件から有効',
