            '최근 에스트라디올 용량이 조금 많아 보여요. 더 늘려도 효과가 빨라지진 않고, 혈전 위험이 조금 올라갈 수 있어요. 너무 걱정하지 마세요. 이 앱의 추정치가 부정확할 수 있어요. 병원에서 호르몬 혈액 검사를 받으면 수치를 보정할 수 있고, 최근 복용량도 한번 살펴봐 주세요.',
