        'disclaimer.title': '면책 조항',
        'disclaimer.text.intro':
            "Oyama's HRT Tracker는 의학적 조언을 제공하지 않습니다. Oyama's HRT Tracker에는 의학 관련 콘텐츠가 포함되어 있지만 그 정확성이나 적시성을 보장하지 않습니다. 귀하의 특정 상황에 완전히 적용되지 않을 수 있습니다. 다음 사항에 유의하세요:",
