        'cal.ekf': 'EKF',
        'cal.ou_kalman': 'OU-Kalman',
        'cal.mipd': 'Hybrid-MIPD',
        'cal.desc.ekf':
            '확장 칼만 필터. 검사를 시간 순서대로 처리하며 개인 진폭과 청소율 추정값을 불확실성과 함께 유지합니다. 영구 기억 —— 모든 검사가 흔적을 남깁니다.',
        'cal.desc.ou_kalman':
            '오른슈타인–울렌벡 칼만 평활. 보정값을 표류하면서 모델로 회귀하는 수준으로 취급하여, 각 검사의 영향이 약 2주에 걸쳐 모델로 감쇠합니다. 고정 계수가 아니라 시간에 따라 변하는 수준을 추적합니다.',
        'cal.desc.mipd':
            '모델 기반 정밀 투여. 모집단 사전분포 아래에서 진폭과 청소율을 MAP로 적합하며 견고한(Student-t) 우도를 사용합니다. 검사가 적으면 모집단으로 수축하고 단일 이상치에 흔들리지 않습니다.',
        'cal.ekf.pro.1': '진폭과 청소율을 함께 학습하며 검사마다 갱신',
        'cal.ekf.pro.2': '자체 불확실성을 추적; 범위 제한으로 발산 안 함',
        'cal.ekf.con.1': '영구 기억 —— 오래된 검사가 계속 추정을 끌어당김',
        'cal.ou_kalman.pro.1': '고정 계수가 아니라 시간에 따라 표류하는 수준을 추적',
        'cal.ou_kalman.pro.2': '최근 검사일수록 가중치가 크고 오래된 것은 자동으로 옅어짐',
        'cal.ou_kalman.con.1': '수준만 보정 —— 곡선 모양이나 반감기는 바꾸지 않음',
        'cal.mipd.pro.1': '이상치에 견고; 데이터가 적으면 모집단 사전에 의존',
